vector<int> mergeV(vector<int> a, vector<int> b){ vector<int> r; size_t i=0,j=0; while(i<a.size()||j<b.size()){
  if(lexicographical_compare(b.begin()+j,b.end(),a.begin()+i,a.end())) r.push_back(a[i++]); else r.push_back(b[j++]); } return r; }
